-- ============================================================
-- 计算机网络原理与实践（完整图谱）导入脚本
-- 源文件：work_cn/kg/data/course_knowledge_graph.json
-- 目标库：personnel_information
-- 规模：7 章 / 57 节 / 145 子节 / 476 个知识点 / 383 条关系
--
-- 用法（PowerShell）：
--   $env:MYSQL_PWD='你的密码'
--   & "C:\mysql\MySQL\MySQL Server 8.0\bin\mysql.exe" -h 127.0.0.1 -u root `
--       --default-character-set=utf8mb4 -D personnel_information `
--       -e "source D:/AAAWork/Knowledge/Knowledge/sql/import_cn_kg.sql"
--
-- 说明：
--   * 新建学科 code=sub_network_kg，不改动原有 subject.id=3“计算机网络”；
--   * 重复执行会先清空本学科知识点与关系，再全量重建；
--   * 知识点 ID 固定 11001..11476，关系 ID 固定 11001..11383；
--   * 关系类型映射：PREREQUISITE→prerequisite；RELATED_TO/CONTRAST_WITH→related；其余→extension；
--   * 章节位置与页码写入 content，原始关系类型保留在 description。
-- ============================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 1;

START TRANSACTION;

-- ---------- 1. 学科 ----------
INSERT INTO `subject` (`name`, `code`, `description`, `icon`, `sort_order`, `status`,
                       `create_by`, `create_time`, `update_by`, `update_time`, `del_flag`)
SELECT '计算机网络原理与实践（完整图谱）', 'sub_network_kg',
       '来源：陈鸣《计算机网络原理与实践》扫描教材 OCR（7 章 / 57 节 / 145 子节）+ 1.1.1 视频逐字稿。共 476 个知识点、383 条知识点关系。由课程知识图谱导入，可重复执行。',
       NULL, 100, '0', 'admin', NOW(), '', NULL, '0'
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `subject` WHERE `code` = 'sub_network_kg');

UPDATE `subject`
SET `name` = '计算机网络原理与实践（完整图谱）', `status` = '0', `del_flag` = '0', `update_time` = NOW()
WHERE `code` = 'sub_network_kg';

SET @subject_id := (SELECT `id` FROM `subject` WHERE `code` = 'sub_network_kg' ORDER BY `id` LIMIT 1);

-- 固定 ID 段若被其它学科占用，下面的插入会失败并整体回滚
SELECT COUNT(*) AS `fixed_id_conflict`
FROM `knowledge_point`
WHERE `id` BETWEEN 11001 AND 11476
  AND `subject_id` <> @subject_id;

-- ---------- 2. 清理本学科旧数据（关系级联删除） ----------
DELETE FROM `knowledge_point` WHERE `subject_id` = @subject_id;

-- ---------- 3. 知识点（476 条） ----------
INSERT INTO `knowledge_point`
(`id`, `subject_id`, `name`, `content`, `difficulty`, `importance`, `type`, `sort_order`,
 `status`, `create_by`, `create_time`, `update_by`, `update_time`, `del_flag`, `attachment`, `video`)
