【类型】技术
【难度】3　【重要度】4
【别名】Manchester encoding
【标签】信道编码、自同步

通过传输NRZ数据与时钟的异或合并时钟和信号。0为低到高跳变，1为高到低跳变。能解决时钟同步，但效率仅50%。',3,4,'技术',64,'0','admin',NOW(),'',NULL,'0',NULL,NULL),
(11065,@subject_id,'4B/5B编码','【位置】第2章 数据通信基础 · 2.3 编码和复用
