【类型】技术
【难度】3　【重要度】3
【标签】信道编码、效率优化

用5个比特编码4个比特数据，插入额外比特减少连续0或1的数量。通常结合NRZI使用，编码效率为80%。',3,3,'技术',65,'0','admin',NOW(),'',NULL,'0',NULL,NULL),
