【标签】多路复用、频谱分配

将可用频带分割成若干子频带，每路信号占用一个特定频带。所有结点在同一时刻使用不同频率资源。',2,4,'技术',66,'0','admin',NOW(),'',NULL,'0',NULL,NULL),
