【标签】多路复用、时隙分配

将传输时间划分为时间片，各结点按次序轮流使用。所有结点在不同时间占用同样的频带宽度。',2,4,'技术',67,'0','admin',NOW(),'',NULL,'0',NULL,NULL),
(11068,@subject_id,'码分复用 (CDM/CDMA)','【位置】第2章 数据通信基础 · 2.3 编码和复用
