每个用户分配唯一正交码片序列。发送时用码片扩展信号带宽（扩频），接收时通过规格化内积解码分离信号。',4,4,'技术',68,'0','admin',NOW(),'',NULL,'0',NULL,NULL),
(11069,@subject_id,'报文交换','【位置】第2章 数据通信基础 · 2.4 交换技术
