【难度】2　【重要度】3
【别名】Message Switching
【标签】交换技术、存储转发

无需建立端到端连接，采用存储转发方式将完整报文发给相邻结点再转发。缺点是对中间结点存储空间要求大，长报文导致时延大，不适合频繁交互。',2,3,'技术',69,'0','admin',NOW(),'',NULL,'0',NULL,NULL),
(11070,@subject_id,'统计复用','【位置】第2章 数据通信基础 · 2.4 交换技术
【页码】教材 p55-59（PDF p67-71）
【类型】技术
【难度】3　【重要度】4
【别名】Statistical Multiplexing
【标签】资源管理、性能优化

分组交换按需使用链路带宽资源的方式。所有用户逐分组共享链路传输能力，以最大速率传输，相比电路交换的预分配，提高了资源利用率和网络可靠性。',3,4,'技术',70,'0','admin',NOW(),'',NULL,'0',NULL,NULL),
(11071,@subject_id,'存储转发时延','【位置】第2章 数据通信基础 · 2.4 交换技术
