CSMA/CD中处理碰撞的重传策略。第n次碰撞后，随机等待k×51.2μs，其中k从0到2^n-1中选择，以自适应扩大取值空间降低再次碰撞概率。',3,3,'算法',139,'0','admin',NOW(),'',NULL,'0',NULL,NULL),
