TCP发送方维护的变量，限制未确认数据量，与接收窗口共同决定发送窗口的最大值。',2,4,'指标',310,'0','admin',NOW(),'',NULL,'0',NULL,NULL),
(11311,@subject_id,'慢启动','【位置】第5章 端到端协议 · 5.6 TCP拥塞控制
【页码】教材 p241-249（PDF p253-261）
【类型】算法
【难度】3　【重要度】4
【别名】Slow Start
【标签】拥塞控制算法、指数增长

TCP初始阶段算法，拥塞窗口从1个MSS开始，每经过一个RTT按指数方式翻倍增长，直至达到阈值或发生丢包。',3,4,'算法',311,'0','admin',NOW(),'',NULL,'0',NULL,NULL),
(11312,@subject_id,'加性增、乘性减 (AIMD)','【位置】第5章 端到端协议 · 5.6 TCP拥塞控制
【页码】教材 p241-249（PDF p253-261）
【类型】算法
【难度】4　【重要度】4
【别名】Additive Increase Multiplicative Decrease
【标签】拥塞控制算法、线性增长、拥塞避免

拥塞避免阶段线性增加窗口（加性增），检测到拥塞时迅速减小窗口（乘性减），使CWin呈锯齿状变化。',4,4,'算法',312,'0','admin',NOW(),'',NULL,'0',NULL,NULL),
(11313,@subject_id,'TCP Reno','【位置】第5章 端到端协议 · 5.6 TCP拥塞控制
【页码】教材 p241-249（PDF p253-261）
【类型】协议
【难度】3　【重要度】4
【标签】拥塞控制、Reno

TCP的一个版本，当收到3个冗余ACK时，将阈值设为0.5×CWin并进入快速恢复阶段，拥塞窗口线性增长。',3,4,'协议',313,'0','admin',NOW(),'',NULL,'0',NULL,NULL),
(11314,@subject_id,'TCP Tahoe','【位置】第5章 端到端协议 · 5.6 TCP拥塞控制
