【类型】协议
【难度】3　【重要度】4
【标签】拥塞控制、Tahoe

TCP的早期版本，无论发生何种丢包事件或超时，均将拥塞窗口重置为1个MSS并转入慢启动阶段。',3,4,'协议',314,'0','admin',NOW(),'',NULL,'0',NULL,NULL),
