VALUES
(11001,11001,11002,'extension','【原关系：组成 PART_OF】主机与端系统是构成计算机网络的基本组成部分，位于网络边缘。',2,NOW()),
(11002,11003,11004,'related','【原关系：对比 CONTRAST_WITH】两者是两种不同的数据交换技术，分组交换采用存储转发且无预留带宽，电路交换建立专用连接并预留带宽。',1,NOW()),
(11003,11005,11006,'extension','【原关系：组成 PART_OF】互联网是由多个网络云互联形成的；因特网是特定的使用TCP/IP协议的互联网实例。',2,NOW()),
(11004,11009,11013,'extension','【原关系：组成 PART_OF】接入网是因特网结构的三大部分之一，负责将端系统连接到边缘路由器。',2,NOW()),
(11005,11010,11002,'extension','【原关系：应用于 APPLIES_TO】端到端原则规定复杂的网络处理功能应置于因特网边缘的主机或端系统中。',2,NOW()),
(11006,11011,11012,'related','【原关系：对比 CONTRAST_WITH】两者是两种主要的应用程序体系结构模式，前者依赖固定IP的服务器，后者为对等方直接通信。',1,NOW()),
(11007,11014,11015,'extension','【原关系：使用 USES】不同层级的ISP通过因特网交换点（IXP）进行对等连接以实现互联。',2,NOW()),
(11008,11016,11014,'extension','【原关系：应用于 APPLIES_TO】多宿是ISP等级结构中除第一层ISP外常见的连接方式，提高可靠性。',2,NOW()),
(11009,11017,11015,'extension','【原关系：使用 USES】内容提供商网络试图经因特网交换点与低层ISP对等连接以节省流量费用。',2,NOW()),
(11010,11019,11003,'extension','【原关系：使用 USES】traceroute通过发送特殊分组并利用分组交换网络的存储转发机制来重建路由路径。',2,NOW()),
(11011,11020,11021,'extension','【原关系：属于 IS_A】网络协议由语法、语义和定时这三个要素共同定义。',2,NOW()),
(11012,11022,11020,'extension','【原关系：组成 PART_OF】网络体系结构是计算机网络各层及其相应协议的集合。',2,NOW()),
(11013,11023,11024,'extension','【原关系：实现 IMPLEMENTS】在垂直通信过程中，高层数据向下传递时通过封装添加控制信息形成新的数据单元。',2,NOW()),
(11014,11025,11020,'extension','【原关系：使用 USES】水平通信指不同主机上对等层之间逻辑上的交互，这种交互是通过网络协议实现的。',2,NOW()),
(11015,11007,11002,'extension','【原关系：组成 PART_OF】该接口运行在主机或端系统的操作系统中，供应用程序请求网络服务。',2,NOW()),
