-- ---------- 5. 校验 ----------
SELECT s.`id` AS `subject_id`, s.`name` AS `subject_name`,
       (SELECT COUNT(*) FROM `knowledge_point` p WHERE p.`subject_id` = s.`id`) AS `points`,
       (SELECT COUNT(*) FROM `knowledge_point_relation` r
          JOIN `knowledge_point` p ON p.`id` = r.`source_id`
         WHERE p.`subject_id` = s.`id`) AS `relations`
FROM `subject` s
WHERE s.`code` = 'sub_network_kg';

SELECT `relation_type`, COUNT(*) AS `cnt`
FROM `knowledge_point_relation` r
JOIN `knowledge_point` p ON p.`id` = r.`source_id`
WHERE p.`subject_id` = @subject_id
GROUP BY `relation_type`;
